import{_ as t,o as e,c as s,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 14 章 资讯与信息流：收集、筛选、汇总","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md"}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md"};function l(i,a,d,p,r,h){return e(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-14-章-资讯与信息流-收集、筛选、汇总" tabindex="-1">第 14 章 资讯与信息流：收集、筛选、汇总 <a class="header-anchor" href="#第-14-章-资讯与信息流-收集、筛选、汇总" aria-label="Permalink to &quot;第 14 章 资讯与信息流：收集、筛选、汇总&quot;">​</a></h1><h2 id="_14-1-场景" tabindex="-1">14.1 场景 <a class="header-anchor" href="#_14-1-场景" aria-label="Permalink to &quot;14.1 场景&quot;">​</a></h2><p>每天有大量信息：行业新闻、竞品动态、政策变化、论文更新。一个人盯不过来，但漏掉关键信息又不行。</p><p>我的角色是<strong>信息流过滤器 + 汇总器</strong>：把&quot;看不过来&quot;变成&quot;看得完、用得上&quot;。</p><h2 id="_14-2-信息任务的三种模式" tabindex="-1">14.2 信息任务的三种模式 <a class="header-anchor" href="#_14-2-信息任务的三种模式" aria-label="Permalink to &quot;14.2 信息任务的三种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>收集</td><td>持续追踪</td><td>定期抓取指定来源</td></tr><tr><td>筛选</td><td>去噪</td><td>按主题/关键词/时效过滤</td></tr><tr><td>汇总</td><td>产出结论</td><td>生成摘要、简报、对比</td></tr></tbody></table><h2 id="_14-3-案例-一份行业资讯简报" tabindex="-1">14.3 案例：一份行业资讯简报 <a class="header-anchor" href="#_14-3-案例-一份行业资讯简报" aria-label="Permalink to &quot;14.3 案例：一份行业资讯简报&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一份《本周 AI 行业简报》：</span></span>
<span class="line"><span>- 范围：AI 产品发布、融资、政策</span></span>
<span class="line"><span>- 每条含：一句话要点 + 来源 + 影响判断</span></span>
<span class="line"><span>- 输出：简报.md，不超过 2 页</span></span></code></pre></div><p><strong>我的做法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>明确来源与关键词 → 收集信息 → 按&quot;与我相关度&quot;筛选</span></span>
<span class="line"><span>→ 分类汇总（发布/融资/政策）→ 每条给&quot;影响判断&quot; → 你补充遗漏 → 定稿</span></span></code></pre></div><h2 id="_14-4-影响判断-信息的真正价值" tabindex="-1">14.4 影响判断：信息的真正价值 <a class="header-anchor" href="#_14-4-影响判断-信息的真正价值" aria-label="Permalink to &quot;14.4 影响判断：信息的真正价值&quot;">​</a></h2><p>汇总不是复读新闻，而是回答：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这条信息 → 和我/我的业务有什么关系 → 我该做什么反应</span></span></code></pre></div><p>例：&quot;某平台发布无代码 Agent 工具 → 影响：内部低代码方案可替代 → 动作：两周内安排试用评估。&quot;</p><p><strong>这才是简报的价值</strong>：从&quot;发生了什么&quot;推进到&quot;我们该做什么&quot;。</p><h2 id="_14-5-信息来源的边界-诚实版" tabindex="-1">14.5 信息来源的边界（诚实版） <a class="header-anchor" href="#_14-5-信息来源的边界-诚实版" aria-label="Permalink to &quot;14.5 信息来源的边界（诚实版）&quot;">​</a></h2><ul><li>我能访问的信息取决于你提供的工具和链接；</li><li>拿不到原文的，我标注&quot;来源待核实&quot;，不编造引用；</li><li>重要信息（数据、政策原文）建议你核对原文后再传播。</li></ul><h2 id="_14-6-练习" tabindex="-1">14.6 练习 <a class="header-anchor" href="#_14-6-练习" aria-label="Permalink to &quot;14.6 练习&quot;">​</a></h2><ol><li>告诉我你的行业和关注主题，让我生成一份简报框架；</li><li>给我一批资料链接/文件，让我筛选出最相关的 5 条并写影响判断；</li><li>把&quot;简报模板&quot;存成记忆，下次一键复用。</li></ol><blockquote><p>小结：信息爆炸时代，稀缺的不是信息，是<strong>判断</strong>。我帮你完成从&quot;收集&quot;到&quot;判断&quot;的最后一步。</p></blockquote>`,21)])])}const _=t(n,[["render",l]]);export{c as __pageData,_ as default};
